styles:
/* CSS CHÍNH: Nền đen, Tiêu đề trắng, Toàn bộ chữ Body trắng, Font Roboto Condensed */
        body { 
            font-family: 'Roboto Condensed', sans-serif; 
            line-height: 1.6; 
            color: #FFFFFF; /* TOÀN BỘ CHỮ BODY MÀU TRẮNG */
            margin: 0; 
            padding: 0; 
            background-color: #000000; /* Nền màu ĐEN TUYỆT ĐỐI */
        }
        .container { 
            max-width: 900px; 
            margin: 20px auto; 
            background-color: #1a1a1a; 
            padding: 20px 30px; 
            border-radius: 8px; 
            box-shadow: 0 0 20px rgba(255, 0, 0, 0.3); /* Vẫn giữ bóng đổ đỏ nhẹ */
        }
        h1, h2, h3 { 
            color: #FFFFFF; /* MÀU TRẮNG cho tiêu đề */
            font-weight: 700; 
            text-transform: uppercase; 
            font-family: 'Roboto Condensed' !important; /* Đảm bảo font */
        }
        h1 { 
            font-size: 2.5em; 
            border-bottom: 3px solid #330000; 
            padding-bottom: 15px; 
            margin-bottom: 25px; 
            text-align: center; 
            letter-spacing: 1px; 
        }
        h2 { 
            font-size: 1.8em; 
            margin-top: 30px; 
            border-left: 5px solid #cc0000; /* Đỏ cho đường kẻ bên trái */
            padding-left: 10px; 
        }
        p { 
            margin-bottom: 15px; 
            color: #FFFFFF; /* TOÀN BỘ CHỮ ĐOẠN VĂN MÀU TRẮNG */
        }
        
        /* Highlight và Message Cuối */
        .highlight { 
            font-weight: bold; 
            color: #FFFFFF; /* ĐÃ CHUYỂN THÀNH MÀU TRẮNG */
        }
        .final-message {
            color: #FFFFFF; /* ĐÃ CHUYỂN THÀNH MÀU TRẮNG */
        }

        /* Bố cục gạch đầu dòng (list-block) - (Để sẵn nếu cần) */
        .list-block {
            margin: 15px 0;
            padding-left: 0; 
        }
        .list-block p {
            margin-bottom: 10px;
            margin-top: 0;
            position: relative;
            padding-left: 25px; 
            color: #FFFFFF;
            font-weight: 400; 
        }
        .list-block p::before {
            content: "—"; /* Ký tự gạch ngang */
            color: #FFFFFF; /* GẠCH NGANG MÀU TRẮNG */
            font-weight: bold;
            display: inline-block; 
            position: absolute;
            left: 0;
        }

        /* Các thành phần phụ khác */
        .note { 
            background-color: #331a1a; 
            padding: 15px; 
            border-left: 5px solid #ffcc00; 
            margin: 20px 0; 
            border-radius: 5px; 
            color: #f0f0f0; 
        }
        img { 
            max-width: 100%; 
            height: auto; 
            display: block; 
            margin: 20px auto; 
            border-radius: 5px; 
        }
